import{_ as t,c as e,o as n,a4 as r}from"./chunks/framework.P4k6vdAm.js";const f=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"docs/overview/glossary.md","filePath":"docs/overview/glossary.md","lastUpdated":1793099931000}'),o={name:"docs/overview/glossary.md"},s=r('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>A2A</strong></td><td>Agent2Agent, an open protocol that lets agents call each other. AireGlu <a href="/docs/agents/">Agents</a> implement it.</td></tr><tr><td><strong>Adapter</strong></td><td>A custom task written in .NET with the AireGlu SDK, for behaviour the built-in tasks don&#39;t provide. See <a href="/docs/developers/adapters.html">Adapters</a>.</td></tr><tr><td><strong>Agent</strong></td><td>An LLM-backed agent hosted by AireGlu, with tools provided by MCP servers. In preview. See <a href="/docs/agents/">Agents</a>.</td></tr><tr><td><strong>Batch invocation</strong></td><td>Running an endpoint once per item in a list, asynchronously, with an optional callback endpoint. See <a href="/docs/triggering/batch-invocation.html">Batch Invocation</a>.</td></tr><tr><td><strong>Connection</strong></td><td>A tenant-wide, reusable configuration for calling an external service, e.g. OAuth client credentials or Office 365 mail. Outbound, unlike endpoint authentication. See <a href="/docs/connections/">Connections</a>.</td></tr><tr><td><strong>Context Data</strong></td><td>The panel in the task editor that lists the paths, functions, variables and secrets you can insert. See <a href="/docs/building/working-with-data.html">Working with Data</a>.</td></tr><tr><td><strong>Correlation ID</strong></td><td>An ID, passed in the <code>x-correlation-id</code> header, that links steps across AireBlocks products in a wider journey. See <a href="/docs/triggering/running.html#correlation-id">Running an Endpoint</a>.</td></tr><tr><td><strong>Debug Mode</strong></td><td>A per-version setting that records each task&#39;s inputs and outputs for troubleshooting. See <a href="/docs/operations/debug-mode.html">Debug Mode</a>.</td></tr><tr><td><strong>Default version</strong></td><td>The version of an endpoint that runs when no version is specified in the URL.</td></tr><tr><td><strong>Endpoint</strong></td><td>An HTTP API hosted by AireGlu that runs a series of tasks when called. See <a href="/docs/overview/key-concepts.html#endpoints">Key Concepts</a>.</td></tr><tr><td><strong>Endpoint Authentication</strong></td><td>Inbound checks that decide who can call an endpoint. See <a href="/docs/endpoint-authentication/">Endpoint Authentication</a>.</td></tr><tr><td><strong>Filter</strong></td><td>A JSONPath condition that decides whether a task runs. See <a href="/docs/building/working-with-data.html#filters">Filters</a>.</td></tr><tr><td><strong>Function</strong></td><td>A built-in utility used inside task settings, written as <code>--*AG:Name(...)*--</code>, e.g. <code>AG:UUID()</code>. See <a href="/docs/building/working-with-data.html#functions">Functions</a>.</td></tr><tr><td><strong>Input schema</strong></td><td>The JSON Schema (or equivalent) that incoming requests are validated against. See <a href="/docs/endpoint-input/input.html">Endpoint Input</a>.</td></tr><tr><td><strong>Job</strong></td><td>A scheduled run of an endpoint. See <a href="/docs/triggering/jobs.html">Jobs</a>.</td></tr><tr><td><strong>Liquid</strong></td><td>The templating language used to build task settings from data. See <a href="/docs/building/liquid.html">Liquid Templating</a>.</td></tr><tr><td><strong>MCP Server</strong></td><td>A configuration that exposes endpoints as tools and resources to AI clients over the Model Context Protocol. See <a href="/docs/mcp-servers/">MCP Servers</a>.</td></tr><tr><td><strong>MESH</strong></td><td>The NHS Message Exchange for Social Care and Health. AireGlu can send MESH messages and receive them with a receiver.</td></tr><tr><td><strong>Path</strong></td><td>A reference to a value in the input or an earlier task&#39;s result, written as <code>--*name*--</code>. See <a href="/docs/building/working-with-data.html#paths">Paths</a>.</td></tr><tr><td><strong>Receiver</strong></td><td>A trigger that runs an endpoint when an email, GovNotify SMS or MESH message arrives. See <a href="/docs/triggering/receivers.html">Receivers</a>.</td></tr><tr><td><strong>Repository</strong></td><td>A Git repository that AireGlu stores and syncs endpoint definitions with. See <a href="/docs/operations/repositories.html">Repositories</a>.</td></tr><tr><td><strong>Route Mapping</strong></td><td>A custom URL that forwards to an endpoint. See <a href="/docs/triggering/route-mapping.html">Route Mapping</a>.</td></tr><tr><td><strong>Secret</strong></td><td>A private, write-only value such as a password or API key. See <a href="/docs/connections/secrets.html">Secrets</a>.</td></tr><tr><td><strong>Stop on Task Failure</strong></td><td>An endpoint setting that stops the run at the first failed task. On by default.</td></tr><tr><td><strong>Task</strong></td><td>One step in an endpoint, e.g. HTTP Request, Mapping or Email. See <a href="/docs/tasks/">Tasks</a>.</td></tr><tr><td><strong>Tenant</strong></td><td>Your organisation&#39;s isolated space in AireGlu. Part of every endpoint URL.</td></tr><tr><td><strong>Transaction ID</strong></td><td>An ID shared by every step of one business transaction, used to trace it in Usage Data. See <a href="/docs/triggering/running.html#transaction-id">Running an Endpoint</a>.</td></tr><tr><td><strong>Usage Data</strong></td><td>The per-request log in the Metrics area. See <a href="/docs/operations/metrics.html">Metrics</a>.</td></tr><tr><td><strong>Variable</strong></td><td>A non-sensitive, tenant-wide setting that can be scoped per endpoint or version. See <a href="/docs/connections/variables.html">Variables</a>.</td></tr><tr><td><strong>Version</strong></td><td>A saved revision of an endpoint. Each version can be enabled, disabled or debugged independently.</td></tr></tbody></table>',2),a=[s];function d(i,c,g,h,l,p){return n(),e("div",null,a)}const m=t(o,[["render",d]]);export{f as __pageData,m as default};
